#!/usr/bin/python3

"""
    Reporting support module.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

from velocity_communicator.log.log import Log
from velocity_communicator.support_services.private.reporting_methods import ReportingPrivate
import smtplib
from email.message import EmailMessage
import json
import socket

class Reporting(ReportingPrivate):
    """

        Class with definition of reporting methods.
        Inherites by ReportingPrivate class which holds private methods.

        Services:
        send_email_report

    """
    logger = Log.get_logger("velocityclient")

    def send_email_report(self, from_mail: str,
                     to_mails: str,
                     subject: str,
                     content: str):
        """
        Can be used to send email notification or
        report.

        :param from_mail: senders email address
        :param to_mails: recipient's email. Multiple 
                         addresses can be separated with comma
        :param email: Email address to send report
        :param subject: Subject of the email
        :param content: Html styled content message string
        """
        if from_mail is None:
            from_mail = "velocity.support@nokia.com"
        message = EmailMessage()
        message['Subject'] = subject
        message['From'] = from_mail
        message['To'] = to_mails
        message.add_header('Content-Type', 'text/html')
        message.set_payload(content)
        s = smtplib.SMTP('mailrelay.int.nokia.com')
        s.send_message(message)
        s.quit()
        self.logger.info('VC: Email report send')

    def send_token_expiration_warning(self, time_remaining):
        """
        Can be used to send warning message to Velocity message bus when token is going to expire.

        :param time_remaining: Time remaining in seconds before token expires.
        """
        hours = int(time_remaining // 3600)
        minutes = int((time_remaining % 3600) // 60)
        self.logger.warning("Token is going to expire, Please generate a new token from Velocity!")
        self.logger.warning(f"Time remaining: {hours} hours {minutes} minutes")
        try:
            self.logger.info(f"Sending warning message to Velocity!")
            user_id = self.get_current_user()
            host = self.get_hostname()
            subject = f"Velocity token is going to expire - {hours} hours!"
            message = f"<p>Velocity token is going to expire on {host} in {hours} hours and {minutes} minutes!<br>Please generate a new token from Velocity and update the token in your application to avoid authentication issues.</p>"
            origin = "Warning from Velocity Communicator!"
            self.send_velocity_message(user_id=user_id["id"], subject=subject, message=message, origin=origin)
            if user_id.get("email"):
                self.send_token_expiration_mail(time_remaining, host, user_id["email"])
        except Exception as e:
            self.logger.warning(f"Error during token expiration warning: {e}")

    def send_token_expiration_mail(self, time_remaining, hostname, email):
        """
        Can be used to send email notification when token is going to expire.

        :param time_remaining: Time remaining in seconds before token expires.
        :param hostname: Hostname where token is used.
        """
        try:
            message = self._token_expiration_message(time_remaining, hostname)
            email_subject = f'[VELOCITY TOKEN EXPIRE] {hostname} token is going to expire in {int(time_remaining // 3600)} hours and {int((time_remaining % 3600) // 60)} minutes!'
            self.send_email_report(from_mail=None,
                                    to_mails=email,
                                    subject=email_subject,
                                    content=message)
        except Exception as e:
            self.logger.warning(
                f'VC: Problems to send report: {e}')

    def send_velocity_message(self, user_id, subject, message, origin):
        """
        Can be used to send message to Velocity message box.

        :param message_body: Message body string. Max length is 255 characters.
        """
        message_body = {
                    "html": True,
                    "userId": user_id,
                    "subject": subject,
                    "message": message,
                    "origin": origin
                }
        # return self.send_message(json.dumps(message_body))
        return self.send_message(message_body)

    def get_hostname(self):
        """Get hostname in cross-platform way"""
        try:
            return socket.gethostname()
        except Exception:
            return "System"
